#!/usr/bin/env python3
"""未污染的 held-out 題庫（矩陣備援評量用）。產生後凍結：不要依它調整合成器／範式、不要讓補教學的 session 看到題目。
輸出 renderer/src/recipe/seed/heldout_all.jsonl（bench_coverage.js 用 --set heldout 讀）。答案由 ref 實際執行得出。"""
import os, random, sys
sys.path.insert(0, os.path.dirname(__file__))
from bench_lib import Bench
B = Bench('heldout_all.jsonl', 20261108); add = B.add; R = random.randint
ri = lambda a, b: (lambda i: '%d\n' % R(a, b))
def rs(al, a, b): return lambda i: ''.join(random.choice(al) for _ in range(R(a, b))) + '\n'
def ints(k, a, b): return lambda i: ' '.join(str(R(a, b)) for _ in range(k)) + '\n'
def nl(a, b, nlo=1, nhi=10): return lambda i: (lambda n: '%d\n%s\n' % (n, ' '.join(str(R(a, b)) for _ in range(n))))(R(nlo, nhi))
def seq(init, coef, mod=None):
    m = (' %% %d' % mod) if mod else ''
    return 'def main():\n    n = int(input())\n    f = %r\n    for i in range(len(f), n + 1):\n        f.append(sum(c * f[i - 1 - j] for j, c in enumerate(%r))%s)\n    print(f[n]%s)\n' % (init, coef, m, m)
def graph(n, m, w=None, directed=True, dag=False):
    es = set(); m = min(m, n * (n - 1) // (1 if directed and not dag else 2))
    while len(es) < m:
        a, b = R(1, n), R(1, n)
        if a == b or (a, b) in es or (not directed and (b, a) in es): continue
        if dag and a > b: a, b = b, a
        es.add((a, b))
    return '%d %d\n' % (n, m) + ''.join('%d %d%s\n' % (a, b, (' %d' % R(1, w)) if w else '') for a, b in sorted(es))
# ---- L0 ----
add('ho-avg4', '四數平均（無條件捨去）', 'L0', '輸入四個整數（每個 -100～100），輸出平均值無條件捨去（往負無限大）。', 'def main():\n    a = list(map(int, input().split()))\n    print(sum(a) // 4)\n', ints(4, -100, 100))
add('ho-range3', '三數全距', 'L0', '輸入三個整數，輸出最大值減最小值。', 'def main():\n    a = list(map(int, input().split()))\n    print(max(a) - min(a))\n', ints(3, -50, 50))
add('ho-leap', '閏年', 'L0', '輸入西元年份 y（1～9999），是閏年印 Y，否則印 N。', 'def main():\n    y = int(input())\n    print("Y" if (y % 4 == 0 and y % 100 != 0) or y % 400 == 0 else "N")\n', lambda i: '%d\n' % random.choice([R(1, 9999), 400 * R(1, 24), 100 * R(1, 99), 4 * R(1, 2400)]))
add('ho-f2c', '攝氏轉華氏', 'L0', '輸入整數攝氏溫度 c（-50～150），輸出華氏溫度 c*9/5+32（無條件捨去成整數）。', 'def main():\n    c = int(input())\n    print(c * 9 // 5 + 32)\n', ri(-50, 150))
add('ho-clock', '分鐘換算', 'L0', '輸入總分鐘數 m（0～100000），輸出「小時 分鐘」兩個整數，用空格分隔。', 'def main():\n    m = int(input())\n    print(m // 60, m % 60)\n', ri(0, 100000))
add('ho-perim', '長方形周長與面積', 'L0', '輸入長和寬兩個正整數（≤1000），輸出周長（只印周長）。', 'def main():\n    a, b = map(int, input().split())\n    print(2 * (a + b))\n', ints(2, 1, 1000))
# ---- L1 ----
add('ho-trib', 'Tribonacci', 'L1', 'T(0)=0，T(1)=0，T(2)=1，T(n)=T(n-1)+T(n-2)+T(n-3)。輸入 n（0≤n≤70），輸出 T(n)。', seq([0, 0, 1], [1, 1, 1]), ri(0, 70))
add('ho-domino', '骨牌鋪 2×n', 'L1', '用 1×2 骨牌鋪滿 2×n 的長方形（1≤n≤80），有幾種鋪法？輸出答案。', seq([1, 1], [1, 1]), ri(1, 80))
add('ho-pell-mod', 'Pell 數取模', 'L1', 'P(0)=0，P(1)=1，P(n)=2P(n-1)+P(n-2)。輸入 n（0≤n≤10^18），輸出 P(n) 除以 10^9+7 的餘數。',
    'def main():\n    n = int(input())\n    M = 10**9 + 7\n    def mul(A, B):\n        return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % M, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % M], [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % M, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % M]]\n    R = [[1, 0], [0, 1]]; T = [[2, 1], [1, 0]]\n    while n:\n        if n & 1: R = mul(R, T)\n        T = mul(T, T); n >>= 1\n    print(R[1][0])\n', lambda i: '%d\n' % random.choice([R(0, 30), R(10**9, 10**18)]))
add('ho-no11', '不含連續 1 的二進位字串數', 'L1', '長度為 n（1≤n≤60）的 0/1 字串中，不含連續兩個 1 的有幾個？輸出答案。', seq([1, 2], [1, 1]).replace('f[n]', 'f[n - 1]') if False else 'def main():\n    n = int(input())\n    a, b = 1, 2\n    for _ in range(n - 1): a, b = b, a + b\n    print(b if n >= 1 else 1)\n', ri(1, 60))
add('ho-lin3', '線性遞推 3 階', 'L1', 'A(0)=1，A(1)=1，A(2)=2，A(n)=A(n-1)+A(n-3)。輸入 n（0≤n≤90），輸出 A(n)。', seq([1, 1, 2], [1, 0, 1]), ri(0, 90))
add('ho-rabbit', '兔子繁殖', 'L1', '第 1、2 個月各有 1 對兔子，之後每個月的對數等於前兩個月對數之和，但每對兔子在第 n 個月是 n-1 月的對數加上 n-2 月的對數的 2 倍。輸入 n（1≤n≤50），輸出第 n 個月的對數。', 'def main():\n    n = int(input())\n    f = [1, 1]\n    for i in range(2, n): f.append(f[-1] + 2 * f[-2])\n    print(f[n - 1])\n', ri(1, 50))
# ---- L2 ----
add('ho-bin3', '二進位能被 3 整除', 'L2', '輸入一個由 0、1 組成的字串（長度 1～30），把它當成二進位數，能被 3 整除印 Y，否則印 N。', 'def main():\n    s = input().strip()\n    print("Y" if int(s, 2) % 3 == 0 else "N")\n', rs('01', 1, 30))
add('ho-count-ab', '"ab" 出現次數', 'L2', '輸入一個由 a、b、c 組成的字串（長度 1～40），輸出子字串 "ab" 出現的次數。', 'def main():\n    s = input().strip()\n    print(sum(1 for i in range(len(s) - 1) if s[i:i + 2] == "ab"))\n', rs('abc', 1, 40))
add('ho-end01', '以 "01" 結尾', 'L2', '輸入一個由 0、1 組成的字串（長度 1～30），若以 "01" 結尾印 yes，否則印 no。', 'def main():\n    s = input().strip()\n    print("yes" if s.endswith("01") else "no")\n', rs('01', 2, 20))
add('ho-a-mod3', 'a 的個數除以 3', 'L2', '輸入一個由 a、b 組成的字串（長度 1～40），輸出 a 的個數除以 3 的餘數。', 'def main():\n    s = input().strip()\n    print(s.count("a") % 3)\n', rs('ab', 1, 40))
add('ho-no-aa', '不含連續兩個 a', 'L2', '輸入一個由 a、b 組成的字串（長度 1～40），若不含連續兩個 a 印 OK，否則印 BAD。', 'def main():\n    s = input().strip()\n    print("BAD" if "aa" in s else "OK")\n', rs('ab', 1, 30))
add('ho-dec-mod7', '十進位除以 7', 'L2', '輸入一個很長的非負整數（十進位字串，長度 1～40），輸出它除以 7 的餘數。', 'def main():\n    print(int(input()) % 7)\n', lambda i: str(R(1, 9)) + ''.join(random.choice('0123456789') for _ in range(R(0, 39))) + '\n')
# ---- L3 ----
add('ho-dag-paths', 'DAG 路徑數', 'L3', '第一行 n m（2≤n≤10），接著 m 行每行 a b 表示 a→b 的邊（保證 a<b，無重邊）。輸出從 1 到 n 的不同路徑數。', 'def main():\n    n, m = map(int, input().split())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split()); adj[a].append(b)\n    d = [0] * (n + 1); d[1] = 1\n    for u in range(1, n + 1):\n        for v in adj[u]: d[v] += d[u]\n    print(d[n])\n', lambda i: (lambda n: graph(n, R(n, n * (n - 1) // 2), dag=True))(R(3, 8)))
add('ho-bfs-dist', '無權最短步數', 'L3', '第一行 n m，接著 m 行每行 a b 表示無向邊。輸出從 1 到 n 最少經過幾條邊，無法到達輸出 -1。', 'def main():\n    from collections import deque\n    n, m = map(int, input().split())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split()); adj[a].append(b); adj[b].append(a)\n    d = [-1] * (n + 1); d[1] = 0; q = deque([1])\n    while q:\n        u = q.popleft()\n        for v in adj[u]:\n            if d[v] < 0: d[v] = d[u] + 1; q.append(v)\n    print(d[n])\n', lambda i: (lambda n: graph(n, R(n - 2, n + 3), directed=False))(R(4, 10)))
add('ho-components', '連通分量數', 'L3', '第一行 n m，接著 m 行每行 a b 表示無向邊。輸出連通分量的個數。', 'def main():\n    n, m = map(int, input().split())\n    p = list(range(n + 1))\n    def f(x):\n        while p[x] != x: p[x] = p[p[x]]; x = p[x]\n        return x\n    for _ in range(m):\n        a, b = map(int, input().split()); p[f(a)] = f(b)\n    print(len({f(i) for i in range(1, n + 1)}))\n', lambda i: (lambda n: graph(n, R(0, n), directed=False))(R(4, 12)))
add('ho-cycle', '有向圖有環嗎', 'L3', '第一行 n m，接著 m 行每行 a b 表示有向邊 a→b。有環印 CYCLE，無環印 DAG。', 'def main():\n    n, m = map(int, input().split())\n    adj = [[] for _ in range(n + 1)]; deg = [0] * (n + 1)\n    for _ in range(m):\n        a, b = map(int, input().split()); adj[a].append(b); deg[b] += 1\n    st = [i for i in range(1, n + 1) if deg[i] == 0]; seen = 0\n    while st:\n        u = st.pop(); seen += 1\n        for v in adj[u]:\n            deg[v] -= 1\n            if deg[v] == 0: st.append(v)\n    print("DAG" if seen == n else "CYCLE")\n', lambda i: (lambda n: graph(n, R(n - 1, n + 3)))(R(4, 8)))
add('ho-longest-dag', 'DAG 最長路', 'L3', '第一行 n m（保證邊 a→b 滿足 a<b），接著 m 行每行 a b w。輸出從 1 出發能走到的最長路徑總權重（只走 1 能到的點；沒邊則 0）。', 'def main():\n    n, m = map(int, input().split())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b, w = map(int, input().split()); adj[a].append((b, w))\n    d = [-1] * (n + 1); d[1] = 0\n    for u in range(1, n + 1):\n        if d[u] < 0: continue\n        for v, w in adj[u]: d[v] = max(d[v], d[u] + w)\n    print(max(d))\n', lambda i: (lambda n: graph(n, R(n - 1, n + 4), w=9, dag=True))(R(4, 9)))
add('ho-reach-from1', '從 1 可達點數', 'L3', '第一行 n m，接著 m 行每行 a b 表示有向邊 a→b。輸出從 1 出發能到達的點的個數（含 1）。', 'def main():\n    n, m = map(int, input().split())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split()); adj[a].append(b)\n    seen = {1}; st = [1]\n    while st:\n        u = st.pop()\n        for v in adj[u]:\n            if v not in seen: seen.add(v); st.append(v)\n    print(len(seen))\n', lambda i: (lambda n: graph(n, R(n - 2, n + 3)))(R(4, 10)))
# ---- L4 ----
add('ho-count-primes', '≤n 的質數個數', 'L4', '輸入 n（1≤n≤10^5），輸出不超過 n 的質數有幾個。', 'def main():\n    n = int(input())\n    s = [True] * (n + 1)\n    c = 0\n    for i in range(2, n + 1):\n        if s[i]:\n            c += 1\n            for j in range(i * i, n + 1, i): s[j] = False\n    print(c)\n', ri(1, 100000))
add('ho-phi', '歐拉函數', 'L4', '輸入正整數 n（≤10^9），輸出 1..n 中與 n 互質的數的個數。', 'def main():\n    n = int(input()); r = n; x = n; p = 2\n    while p * p <= x:\n        if x % p == 0:\n            while x % p == 0: x //= p\n            r -= r // p\n        p += 1\n    if x > 1: r -= r // x\n    print(r)\n', ri(1, 10**9))
add('ho-perfect', '完全數', 'L4', '輸入正整數 n（≤10^5），若它等於所有真因數（不含自己）之和印 YES，否則印 NO。', 'def main():\n    n = int(input())\n    print("YES" if n > 1 and sum(d for d in range(1, n) if n % d == 0) == n else "NO")\n', lambda i: '%d\n' % random.choice([6, 28, 496, 8128, R(1, 100000), R(1, 1000)]))
add('ho-halve', '減到 1 的步數', 'L4', '輸入正整數 n（≤10^9）。每步：偶數就除以 2，奇數就減 1。輸出變成 0 需要幾步。', 'def main():\n    n = int(input()); c = 0\n    while n:\n        n = n // 2 if n % 2 == 0 else n - 1; c += 1\n    print(c)\n', ri(1, 10**9))
add('ho-base-k', '轉成 k 進位', 'L4', '第一行整數 n（0≤n≤10^9），第二行整數 k（2≤k≤9）。輸出 n 的 k 進位表示。', 'def main():\n    n = int(input()); k = int(input())\n    if n == 0: print(0); return\n    s = ""\n    while n: s = str(n % k) + s; n //= k\n    print(s)\n', lambda i: '%d\n%d\n' % (R(0, 10**9), R(2, 9)))
add('ho-sum-sq', '平方和', 'L4', '輸入 n（1≤n≤10^6），輸出 1^2+2^2+…+n^2。', 'def main():\n    n = int(input())\n    print(sum(i * i for i in range(1, n + 1)))\n', ri(1, 10**6))
# ---- L5 ----
add('ho-valid-3', '三種括號配對', 'L5', '輸入一個只含 ()[]{} 的字串（長度 1～30），括號正確配對印 YES，否則印 NO。', 'def main():\n    s = input().strip(); st = []; P = {")": "(", "]": "[", "}": "{"}\n    for c in s:\n        if c in "([{": st.append(c)\n        elif not st or st.pop() != P[c]: print("NO"); return\n    print("YES" if not st else "NO")\n', rs('()[]{}', 1, 14))
add('ho-postfix', '後序運算', 'L5', '輸入一行後序（RPN）運算式，運算元是 0～9 的個位數，運算子是 + - *，以空格分隔。輸出結果。', 'def main():\n    st = []\n    for t in input().split():\n        if t.isdigit(): st.append(int(t))\n        else:\n            b = st.pop(); a = st.pop(); st.append(a + b if t == "+" else a - b if t == "-" else a * b)\n    print(st[0])\n', lambda i: (lambda k: (lambda ops: ' '.join(ops))((lambda: [str(R(0, 9)), str(R(0, 9)), random.choice('+-*')] + sum([[str(R(0, 9)), random.choice('+-*')] for _ in range(k)], []))()))(R(0, 3)) + '\n')
add('ho-hist', '直方圖最大矩形', 'L5', '第一行 n，第二行 n 個正整數表示直方圖各柱高度（每柱寬 1）。輸出最大矩形面積。', 'def main():\n    n = int(input()); h = list(map(int, input().split())); best = 0\n    for i in range(n):\n        m = h[i]\n        for j in range(i, n):\n            m = min(m, h[j]); best = max(best, m * (j - i + 1))\n    print(best)\n', nl(1, 9, 1, 8))
add('ho-warmer', '幾天後更暖', 'L5', '第一行 n，第二行 n 個整數表示每天溫度。對每一天輸出還要幾天才會遇到更高的溫度，沒有則輸出 0，以空格分隔。', 'def main():\n    n = int(input()); t = list(map(int, input().split())); r = []\n    for i in range(n):\n        d = 0\n        for j in range(i + 1, n):\n            if t[j] > t[i]: d = j - i; break\n        r.append(d)\n    print(*r)\n', nl(1, 30, 1, 9))
add('ho-decode', '展開 k[字串]', 'L5', '輸入形如 3[ab] 的字串，數字後方括號內的字串重複該次數，可巢狀，如 2[a2[b]] 得 abbabb。輸入長度 ≤ 30，輸出展開結果。', 'def main():\n    s = input().strip(); st = [("", 1)]; cur = ""; num = 0\n    for c in s:\n        if c.isdigit(): num = num * 10 + int(c)\n        elif c == "[": st.append((cur, num)); cur = ""; num = 0\n        elif c == "]": p, k = st.pop(); cur = p + cur * k\n        else: cur += c\n    print(cur)\n', lambda i: random.choice(['%d[%s]' % (R(1, 4), 'ab'[:R(1, 2)]), '%d[a%d[b]]' % (R(1, 3), R(1, 3)), 'x%d[yz]w' % R(1, 5), '%d[%d[c]]d' % (R(1, 3), R(1, 3))]) + '\n')
add('ho-longest-paren', '最長合法括號', 'L5', '輸入一個只含 ( 和 ) 的字串（長度 1～30），輸出最長的連續合法括號子字串長度。', 'def main():\n    s = input().strip(); st = [-1]; best = 0\n    for i, c in enumerate(s):\n        if c == "(": st.append(i)\n        else:\n            st.pop()\n            if not st: st.append(i)\n            else: best = max(best, i - st[-1])\n    print(best)\n', rs('()', 1, 20))
# ---- L6 ----
add('ho-josephus', '約瑟夫問題', 'L6', '輸入 n k（1≤n≤1000，1≤k≤10）：n 個人圍成圓圈編號 1..n，從 1 開始報數，每數到 k 的人出列，輸出最後留下的人的編號。', 'def main():\n    n, k = map(int, input().split()); a = list(range(1, n + 1)); i = 0\n    while len(a) > 1:\n        i = (i + k - 1) % len(a); a.pop(i)\n    print(a[0])\n', lambda i: '%d %d\n' % (R(1, 1000), R(1, 10)))
add('ho-window-max', '滑動視窗最大值之和', 'L6', '第一行 n w，第二行 n 個整數。對每個長度為 w 的連續視窗取最大值，輸出所有視窗最大值的總和。', 'def main():\n    n, w = map(int, input().split()); a = list(map(int, input().split()))\n    print(sum(max(a[i:i + w]) for i in range(n - w + 1)))\n', lambda i: (lambda n: (lambda w: '%d %d\n%s\n' % (n, w, ' '.join(str(R(-20, 20)) for _ in range(n))))(R(1, n)))(R(1, 12)))
add('ho-lis-len', '最長嚴格遞增子序列', 'L6', '第一行 n，第二行 n 個整數。輸出最長嚴格遞增子序列的長度。', 'def main():\n    n = int(input()); a = list(map(int, input().split())); d = [1] * n\n    for i in range(n):\n        for j in range(i):\n            if a[j] < a[i]: d[i] = max(d[i], d[j] + 1)\n    print(max(d))\n', nl(1, 30, 1, 12))
add('ho-kth-large', '第 k 大', 'L6', '第一行 n k，第二行 n 個整數。輸出第 k 大的數（重複的數要重複算，即排序後由大到小的第 k 個）。', 'def main():\n    n, k = map(int, input().split()); a = sorted(map(int, input().split()), reverse=True)\n    print(a[k - 1])\n', lambda i: (lambda n: '%d %d\n%s\n' % (n, R(1, n), ' '.join(str(R(-30, 30)) for _ in range(n))))(R(1, 10)))
add('ho-intervals', '合併區間數', 'L6', '第一行 n，接著 n 行每行兩個整數 l r（l≤r，閉區間）。輸出把有重疊（含端點相接）的區間合併後剩幾個區間。', 'def main():\n    n = int(input()); v = sorted(tuple(map(int, input().split())) for _ in range(n)); c = 0; end = None\n    for l, r in v:\n        if end is None or l > end: c += 1; end = r\n        else: end = max(end, r)\n    print(c)\n', lambda i: (lambda n: '%d\n' % n + ''.join('%d %d\n' % (lambda a: (a, a + R(0, 4)))(R(0, 25)) for _ in range(n)))(R(1, 8)))
add('ho-two-sum', '和為 k 的配對數', 'L6', '第一行 n k，第二行 n 個整數。輸出有幾組 (i, j)（i<j）滿足 a[i]+a[j]=k。', 'def main():\n    n, k = map(int, input().split()); a = list(map(int, input().split()))\n    print(sum(1 for i in range(n) for j in range(i + 1, n) if a[i] + a[j] == k))\n', lambda i: (lambda n: '%d %d\n%s\n' % (n, R(2, 14), ' '.join(str(R(0, 9)) for _ in range(n))))(R(2, 10)))
# ---- other ----
add('ho-word-freq', '最常出現的單字', 'other', '輸入一行以空格分隔的小寫單字，輸出出現最多次的單字；次數相同輸出字典序最小的。', 'def main():\n    w = input().split(); c = {}\n    for x in w: c[x] = c.get(x, 0) + 1\n    print(sorted(c, key=lambda x: (-c[x], x))[0])\n', lambda i: ' '.join(random.choice(['cat', 'dog', 'bird', 'fish']) for _ in range(R(1, 12))) + '\n')
add('ho-rle-dec', '游程解碼', 'other', '輸入形如 a3b2c1 的字串（字母後接 1～9 的次數），輸出展開後的字串。', 'def main():\n    s = input().strip(); print("".join(s[i] * int(s[i + 1]) for i in range(0, len(s), 2)))\n', lambda i: ''.join(random.choice('abcxyz') + str(R(1, 9)) for _ in range(R(1, 6))) + '\n')
add('ho-pal-sub', '回文子字串數', 'other', '輸入一個小寫字串（長度 1～20），輸出其中回文子字串的個數（位置不同算不同）。', 'def main():\n    s = input().strip()\n    print(sum(1 for i in range(len(s)) for j in range(i, len(s)) if s[i:j + 1] == s[i:j + 1][::-1]))\n', rs('ab', 1, 14))
add('ho-transpose', '矩陣轉置', 'other', '第一行 r c，接著 r 行每行 c 個整數。輸出轉置後的矩陣（c 行 r 列，同行以空格分隔）。', 'def main():\n    r, c = map(int, input().split()); m = [input().split() for _ in range(r)]\n    for j in range(c): print(" ".join(m[i][j] for i in range(r)))\n', lambda i: (lambda r, c: '%d %d\n' % (r, c) + ''.join(' '.join(str(R(0, 9)) for _ in range(c)) + '\n' for _ in range(r)))(R(1, 4), R(1, 4)))
add('ho-pascal', '巴斯卡三角列', 'other', '輸入 n（0≤n≤30），輸出巴斯卡三角形第 n 列（第 0 列是 1），以空格分隔。', 'def main():\n    n = int(input()); r = [1]\n    for _ in range(n): r = [1] + [r[i] + r[i + 1] for i in range(len(r) - 1)] + [1]\n    print(*r)\n', ri(0, 30))
add('ho-anagram', '是否變位詞', 'other', '兩行小寫字串。若第二行是第一行重新排列而成（字母與次數都相同）印 YES，否則印 NO。', 'def main():\n    a = input().strip(); b = input().strip()\n    print("YES" if sorted(a) == sorted(b) else "NO")\n', lambda i: (lambda a: '%s\n%s\n' % (a, ''.join(random.sample(a, len(a))) if R(0, 1) else ''.join(random.choice('abc') for _ in range(len(a)))))(''.join(random.choice('abc') for _ in range(R(1, 6)))))
